    'permission_interact_with_telegram_bot_description' => 'Використання підключеного асистента власника та Telegram-процесів.',
    'permission_issue_customer_class_passes_description' => 'Видача куплених абонементів клієнтам і запуск підбору записів.',
    'permission_manage_customer_class_passes_description' => 'Редагування абонементів, оплат, заморозок, строків дії та історії коригувань.',
    'permission_correct_closed_classes_description' => 'Додавання або видалення клієнтів із уже завершених занять, видалення записів у закритому вікні скасування та зміна використаних занять абонемента.',
    'permission_record_customer_payments_description' => 'Фіксація точкових готівкових оплат за заняття й абонементи без доступу до фінансових сторінок.',
    'permission_manage_studio_cashflow_description' => 'Звірка кас, внесення витрат і фіксація внесення або вилучення готівки без доступу до загальних звітів.',
    'permission_view_studio_financial_reports_description' => 'Перегляд історії платежів, фінансового звіту, заробітку та оренд.',
    'permission_manage_studio_payroll_description' => 'Налаштування моделей зарплати, закриття та анулювання зарплатних періодів.',
    'permission_view_activity_log_description' => 'Перегляд дій в акаунті та аудиту.',
    'permission_mark_attendance_description' => 'Відмітка записів як відвіданих, пропущених, скасованих або активних.',
    'permission_manage_trainers_description' => 'Створення тренерів, входів для персоналу, замін і прав тренерів.',
    'permission_manage_studio_settings_description' => 'Редагування залів, локацій, форматів, інтеграцій і бренду студії.',
    'permission_manage_schedule_details' => 'Дозволяє створювати серії та разові заняття, змінювати час, зал, формат або тренера, а також скасовувати чи відновлювати елементи розкладу. Для скасування заняття, на яке вже є записи, також потрібне право керувати записами.',
    'permission_manage_clients_details' => 'Дозволяє відкривати список і профілі клієнтів, створювати та редагувати контактні дані, а також користуватися імпортом і експортом клієнтів. Не дає права видавати або редагувати придбані абонементи.',
    'permission_manage_bookings_details' => 'Дозволяє шукати клієнтів, записувати їх на групові заняття, створювати швидкі записи на персональні заняття чи оренду, змінювати статуси записів і скасовувати їх у межах звичайного вікна скасування. Для змін після заняття або дедлайну потрібне право коригувати закриті заняття.',
    'permission_manage_website_leads_details' => 'Дозволяє переглядати вхідні заявки із сайту, створювати й оновлювати заявки, змінювати їхній статус і перетворювати на клієнтів студії. Не надає загального доступу до всіх профілів клієнтів.',
    'permission_interact_with_telegram_bot_details' => 'Дозволяє користуватися підключеним асистентом власника й авторизованими Telegram-процесами цієї студії. Для окремих чутливих дій усе одно потрібні відповідні права на розклад, клієнтів, абонементи, фінанси, зарплату або події.',
    'permission_issue_customer_class_passes_details' => 'Дозволяє видати новий придбаний абонемент з активного тарифу, зафіксувати початкову сплачену суму та підібрати до нього наявні відповідні записи. Не дозволяє пізніше змінювати строк дії, заморозку, статус або баланс занять.',
    'permission_manage_customer_class_passes_details' => 'Дозволяє відкривати придбані абонементи, змінювати їхній статус і дати життєвого циклу, заморожувати та розморожувати, звіряти записи й фіксувати коригування занять або строку дії із зазначенням причини. Для нової точкової оплати потрібне окреме право фіксувати оплати клієнтів.',
    'permission_correct_closed_classes_details' => 'Дозволяє вносити зміни заднім числом після завершення заняття або закриття вікна скасування: додавати чи видаляти клієнтів, скасовувати закриті заняття або записи та коригувати використані заняття абонемента. Ці дії змінюють історичні дані записів і абонементів.',
    'permission_record_customer_payments_details' => 'Дозволяє фіксувати точкові оплати за неоплачені записи на заняття та видані вручну абонементи. Не надає доступу до платіжних звітів, звірки каси, витрат, внесень або вилучень коштів.',
    'permission_manage_studio_cashflow_details' => 'Дозволяє відкривати сторінки каси й витрат, звіряти фактичну готівку, керувати категоріями витрат і фіксувати витрати, внесення або вилучення коштів. Не надає доступу до загальних звітів з оплат, заробітку, оренди чи зарплати.',
    'permission_view_studio_financial_reports_details' => 'Дозволяє переглядати історію оплат, фінансовий звіт, звіти із заробітку, персональних занять та оренди. Це право на перегляд і саме по собі не дозволяє операції з касою, зміну витрат або керування зарплатними періодами.',
    'permission_manage_studio_payroll_details' => 'Дозволяє переглядати деталі зарплати тренерів, призначати й налаштовувати моделі зарплати, задавати періодичність і закривати або анулювати зарплатні періоди. Ці дії змінюють зарплатні записи студії.',
    'permission_view_activity_log_details' => 'Дозволяє переглядати журнал дій студії та пов’язані журнали доставки клієнтських сповіщень і Telegram-сповіщень. Показує, хто виконував зафіксовані дії, але не дає права повторювати їх.',
    'permission_mark_attendance_details' => 'Дозволяє змінювати статус запису на «відвідано», «не прийшов/прийшла», «скасовано» або «записано» з карток розкладу та дашборду. Не дозволяє створювати елементи розкладу чи редагувати профілі клієнтів.',
    'permission_manage_trainers_details' => 'Дозволяє створювати й редагувати профілі тренерів, локації, напрямки, приватні години, входи для персоналу, заміни та права інших тренерів. Тренер із цим правом може змінювати доступ іншого працівника.',
    'permission_manage_studio_settings_details' => 'Дозволяє змінювати локації, зали, напрямки, формати занять, службові приміщення, інтеграції, API-токени, налаштування сповіщень і параметри бренду. Може впливати на роботу всієї студії.',
    'permission_group_schedule_and_classes' => 'Розклад і заняття',
